import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"EUV 对多重曝光的成本交叉","description":"","frontmatter":{"title":"EUV 对多重曝光的成本交叉","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-vs-multipattern-cost-crossover.md","filePath":"litho/euv-vs-multipattern-cost-crossover.md","lastUpdated":1789023840000}'),d={name:"litho/euv-vs-multipattern-cost-crossover.md"};function h(_,a,u,m,V,A){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="euv-对多重曝光的成本交叉" tabindex="-1">EUV 对多重曝光的成本交叉 <a class="header-anchor" href="#euv-对多重曝光的成本交叉" aria-label="Permalink to &quot;EUV 对多重曝光的成本交叉&quot;">​</a></h1><div class="epigraph"><p>交叉点是「一张 EUV 替换几次浸没 + 切线」在周期、套刻与掩模上的平衡，随剂量、pellicle 和层类型移动。</p><footer>—— 对照 ASML 与代工对 EUV 插入临界层、浸没保留次临界层的公开叙事</footer></div><p><a href="/litho/cost-per-layer-wafer">上一课</a>给出按层加总。缺口是决策：某层该不该从 LELE/SAQP 迁 EUV。本课钉成本交叉。<a href="/litho/duv-multipattern-cost">DUV 多重代价</a> 已写 7/5 nm 结构；这里收成交叉逻辑。机台本身多贵，留给[下一课](/litho/tool-price-depreciation）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 单次买回二维与减张数、减同层套刻；付出源功率、随机剂量、掩模、pellicle。浸没多重买分辨率，付出步骤与设计规则。交叉点按层：密孔可能早迁，宽松金属可能永不迁。高 NA 再改一次交叉（半场、更贵机台、薄胶）。</p><p>缺口是<strong>移动的平衡</strong>，不是「EUV 总更贵」或「总更便宜」。不填美元交叉点。</p><h3 id="公开叙事可引用结构" tabindex="-1">公开叙事可引用结构 <a class="header-anchor" href="#公开叙事可引用结构" aria-label="Permalink to &quot;公开叙事可引用结构&quot;">​</a></h3><p>ASML 把浸没定位为多重与次临界工作马，NXE 为临界层。混跑与 cross-match 是交叉之后仍存在的状态，不是过渡年特写。</p><p><span class="marginnote">随机悬崖可以把「光学上该迁 EUV」的层留在多重，或迫使 EUV 双重。交叉含随机，不只含 wph。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对候选层：列 DUV 模块步骤 vs EUV 模块步骤，加套刻风险、设计自由度、掩模周期。灵敏度扫剂量与pellicle T。决策是 DTCO，不是财务单独。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成本差 Δ ≈ (n_DUV · c_imm − c_EUV) + 掩模差 + 良率差。n_DUV 随节距涨；c_EUV 随剂量涨。交叉发生在 n 足够大且 c_EUV 被功率/pellicle 压下来时。这是结构式，系数来自当时厂数据，课文不编。</p>',13)),(e(),n(c,null,{default:r(()=>[E(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%88%86%E8%A7%A3%E6%AC%A1%E6%95%B0%22%5D%20--%3E%20DUV%5B%22%E6%B5%B8%E6%B2%A1%E6%A8%A1%E5%9D%97%E6%88%90%E6%9C%AC%22%5D%0A%20%20DOSE%5B%22EUV%20%E5%89%82%E9%87%8F%20%2F%20pellicle%22%5D%20--%3E%20EUV%5B%22EUV%20%E6%A8%A1%E5%9D%97%E6%88%90%E6%9C%AC%22%5D%0A%20%20DUV%20--%3E%20X%5B%22%E6%8C%89%E5%B1%82%E4%BA%A4%E5%8F%89%22%5D%0A%20%20EUV%20--%3E%20X%0A%20%20STO%5B%22%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20X%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测某年全球交叉。不把所有层一次迁完。交叉不消除浸没机需求。</p><p>后课默认：层决策看交叉结构；下一课机台价格与折旧如何把 c_imm、c_EUV 变成会计数字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交叉按层，随分解次数、EUV 剂量与随机移动。</li><li>混跑是稳态；浸没仍服务次临界层。</li><li>只比较结构，不编美元交叉点。</li><li>出处：ASML/代工公开插入叙事；与多重代价课衔接。</li></ul>',5))])}const v=o(d,[["render",h]]);export{f as __pageData,v as default};
